 function box(x,y,w,h){rect(x,y,w,h,'#090a12');outline(x,y,w,h,C.cream,3)}
 function drawBattleBox(){box(245,304,470,180);if(state==='enemy'){heartDraw(heart.x,heart.y,18,C.red);for(let b of bullets){if(b.type==='star'){ctx.save();ctx.translate(b.x,b.y);ctx.rotate(b.rot||0);text('✦',0,0,23,'#ffd86d','center');ctx.restore()}else if(b.type==='horseshoe'){text('⌒',b.x,b.y,26,'#ffad72','center')}else heartDraw(b.x,b.y,15,b.color||'#ff758b')}}else if(state==='fight'){rect(270,362,420,14,'#493044');rect(270,362,420*enemyHp/100,14,'#dd667d');outline(270,362,420,14,C.cream,2);rect(478,342,4,54,'#fff1dc');let mx=278+(Math.sin(attackTime*4)+1)*204;rect(mx,348,9,42,C.gold);text('PRESS Z NEAR THE CENTER!',480,425,14,C.muted,'center')}else if(['intro','talk','result','win','lose','menu','submenu','mercy'].includes(state)){let message=state==='intro'?dialogue[line]||'':state==='talk'||state==='result'?dialogue[0]:state==='win'?winText:state==='lose'?'Your heart slows. But every race has another lap.':state==='menu'?'Haru bounces on her toes, ready for another lap.':state==='submenu'?'What would you like to do?':'The finish line is behind her. Haru is all smiles.';let lines=wrapText(message,38).slice(0,5);text('♥',269,348,20,C.red);lines.forEach((line,i)=>text(line,490,338+i*25,17,C.cream,'center'));if(['intro','talk','result','win','lose'].includes(state))text('Z  NEXT',684,463,12,'#8e899f','right')}}
-function drawMenu(){if(state==='enemy'||state==='fight'||state==='win'||state==='lose')return;box(95,510,770,105);if(state==='intro'||state==='talk'||state==='result'){text('Z  CONTINUE',830,589,14,C.gold,'right');return}if(state==='submenu'){text(sublist[sub]||'',145,548,19,C.cream);text('X BACK',830,589,13,C.muted,'right');return}if(state==='mercy'){text('Spare Haru?',145,548,19,C.cream);text('Z YES     X NOT YET',830,589,14,C.gold,'right');return}if(state==='fight'){return}const xs=[146,345,545,745];for(let i=0;i<4;i++){let selected=i===menu;let color=selected?C.gold:C.cream;if(selected)heartDraw(xs[i]-31,548,15,C.red);text(menuNames[i],xs[i],548,22,color,'center');}text('Haru bounces on her toes.',480,584,13,'#aaa8be','center');}
+function drawMenu(){if(state==='enemy'||state==='fight'||state==='win'||state==='lose')return;box(95,510,770,105);if(state==='intro'||state==='talk'||state==='result'){text('Z  CONTINUE',830,589,14,C.gold,'right');return}if(state==='submenu'){text(sublist[sub]||'',145,548,19,C.cream);text('X BACK',830,589,13,C.muted,'right');return}if(state==='mercy'){text('Spare Haru?',145,548,19,C.cream);text('Z YES     X NOT YET',830,589,14,C.gold,'right');return}if(state==='fight'){return}const xs=[146,345,545,745];for(let i=0;i<4;i++){let selected=i===menu;let color=selected?C.gold:C.cream;if(selected)heartDraw(xs[i]-44,548,15,C.red);text(menuNames[i],xs[i],548,22,color,'center');}text('Haru bounces on her toes.',480,584,13,'#aaa8be','center');}
 function draw(){background();status();horseGirl();drawBattleBox();drawMenu();if(floating&&floatT>0){text(floating,480,250,17,C.gold,'center')}if(shake>0){/* shake is applied to player only */}}
 function chooseMenu(){let item=menuNames[menu];sound(520,.05);if(item==='FIGHT'){state='fight';attackTime=0;return}if(item==='ACT'){sublist=['Cheer her on','Ask about her dream','Race her to the line'];sub=0;state='submenu';return}if(item==='ITEM'){sublist=hp<maxHp?['Strawberry shortcake  +8 HP','Pocket carrot  +5 HP']:['Your bag is empty.'];sub=0;state='submenu';return}if(item==='MERCY'){if(kindness>=3){state='mercy'}else{state='talk';dialogue=[`Haru still wants to race! (${kindness}/3 heart-to-hearts)`]}return}}
 function selectSub(){let item=sublist[sub];if(menu===1){if(sub===0){kindness++;dialogue=['You cheer with all your heart.','Haru’s ears perk up! Her smile shines brighter.']}else if(sub===1){kindness++;dialogue=['You ask what keeps her running.','“Because I believe I can make someone smile!”']}else{kindness+=2;dialogue=['You challenge Haru to a friendly sprint.','She takes off, then circles back laughing!']};state='result';endTalk()}else if(menu===2){if(hp<maxHp&&(sub===0||sub===1)){let heal=sub===0?8:5;hp=Math.min(maxHp,hp+heal);dialogue=[`You share a ${sub===0?'strawberry shortcake':'pocket carrot'}.`,`HP restored by ${heal}! Haru says it looks delicious.`];sublist=['Your bag is empty.'];state='result';endTalk()}else{dialogue=['You rummage around.','Nothing left in your bag!'];state='result';endTalk()}}}
 function endTalk(){kindness=Math.min(3,kindness);floatT=0;}
